22:   'Origin': 'https://cinejoy.pk',
23:   'Referer': 'https://cinejoy.pk/',
24:   'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/108.0.5359.211 Safari/537.36',
25:   'Accept': '*/*'
