          console.log('Content-Length:', res.headers['content-length']);
          console.log('Bytes read:', len);
          if (res.statusCode === 206 && len === 1000 && res.headers['content-range'].startsWith('bytes 500-1499/')) {
            console.log('-> Range 206: PASS');
            resolve();
          } else {
            reject(new Error('Range 206 failed'));
          }
        });
      });
      req.on('error', reject);
      req.end();
    });

    // 2. Test Memory Footprint during full segment download
    console.log('--- TEST 2: Memory Footprint & Streaming ---');
    const memBefore = process.memoryUsage();
    await new Promise((resolve, reject) => {
      const segUrl = 'https://lightspeed.st/hls/8e7e7dad-ed31-47d4-8243-925232bdeae3/1/360p/seg-v0.png';
      http.get({
        hostname: '127.0.0.1',
        port,
        path: '/hls/proxy?url=' + encodeURIComponent(segUrl)
      }, (res) => {
        let total = 0;
        res.on('data', c => total += c.length);
        res.on('end', () => {
          const memAfter = process.memoryUsage();
          const heapDiffMB = (memAfter.heapUsed - memBefore.heapUsed) / 1024 / 1024;
          const rssMB = memAfter.rss / 1024 / 1024;
          console.log('Total segment bytes transferred:', total);
          console.log('Heap Used (MB):', (memAfter.heapUsed / 1024 / 1024).toFixed(2));
          console.log('Heap Diff (MB):', heapDiffMB.toFixed(2));
          console.log('RSS (MB):', rssMB.toFixed(2));
          if (rssMB < 100) {
            console.log('-> Memory Footprint: PASS (<100MB)');
            resolve();
          } else {
            reject(new Error('Memory exceeded limit'));
          }
        });
      }).on('error', reject);
    });

    // 3. Test Client Abort / Disconnect handling
    console.log('--- TEST 3: Client Abort / Disconnect ---');
    await new Promise((resolve, reject) => {
      const segUrl = 'https://lightspeed.st/hls/8e7e7dad-ed31-47d4-8243-925232bdeae3/1/360p/seg-v0.png';
      const req = http.get({
        hostname: '127.0.0.1',
        port,
        path: '/hls/proxy?url=' + encodeURIComponent(segUrl)
      }, (res) => {
        res.on('data', (c) => {
          // Immediately abort client connection upon receiving first chunk
          console.log('Received first chunk (' + c.length + ' bytes), aborting client request...');
          req.destroy();
          setTimeout(() => {
            console.log('Server survived client disconnect without crash!');
            resolve();
          }, 300);
        });
      });
      req.on('error', (err) => {
        // Expected client error since req.destroy() was called
      });
    });

    // 4. Test SSRF & Target URL validation
    console.log('--- TEST 4: SSRF & URL Validation ---');
    const ssrfUrls = [
      'ftp://example.com/file',
      'javascript:alert(1)',
      'file:///etc/passwd',
      'invalid-url'
    ];
    for (const u of ssrfUrls) {
      await new Promise((resolve) => {
        http.get({
          hostname: '127.0.0.1',
          port,
          path: '/hls/proxy?url=' + encodeURIComponent(u)
        }, (res) => {
          console.log('SSRF check for ' + u + ' -> Status: ' + res.statusCode);
          if (res.statusCode === 400) resolve();
          else throw new Error('Expected 400 for ' + u);
        });
      });
    }
    console.log('-> SSRF URL Validation: PASS');

  } finally {
    await stopServer();
    console.log('Server stopped cleanly.');
  }
}

adversarialTest().then(() => {
  console.log('ALL ADVERSARIAL CHECKS PASSED');
  process.exit(0);
}).catch(err => {
  console.error('ADVERSARIAL CHECK FAILED:', err);
  process.exit(1);
});
